def is_valid_sudoku(board):
    seen = set()
    for r in range(9):
        for c in range(9):
            v = board[r][c]
            if v == '.': continue
            for key in (f'{v} in row {r}', f'{v} in col {c}', f'{v} in box {r//3}-{c//3}'):
                if key in seen: return False
                seen.add(key)
    return True

