        cnt = Counter(c for c in board[r] if c != '.')
        if any(v > 1 for v in cnt.values()): return False
    for c in range(9):
        cnt = Counter(board[r][c] for r in range(9) if board[r][c] != '.')
        if any(v > 1 for v in cnt.values()): return False
