def spiral_order(matrix):
    if not matrix: return []
    top, bottom, left, right = 0, len(matrix)-1, 0, len(matrix[0])-1
    res = []
    while top <= bottom and left <= right:
        for c in range(left, right+1): res.append(matrix[top][c])
        top += 1
        for r in range(top, bottom+1): res.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            for c in range(right, left-1, -1): res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            for r in range(bottom, top-1, -1): res.append(matrix[r][left])
            left += 1
    return res

def spiral_order(matrix):
    if not matrix: return []
    if len(matrix) == 1:
        return list(matrix[0])
    top = list(matrix[0])
    rest = [list(row[:-1]) for row in matrix[1:]]
    rest = list(zip(*rest))[::-1]
    return top + spiral_order([list(r) for r in rest])

