def game_of_life(board):
    m, n = len(board), len(board[0])
    def live(r, c):
        cnt = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and board[nr][nc] & 1:
                    cnt += 1
        return cnt
    for r in range(m):
        for c in range(n):
            cnt = live(r, c)
            if board[r][c] == 1 and cnt in (2, 3): board[r][c] |= 2
            if board[r][c] == 0 and cnt == 3: board[r][c] |= 2
    for r in range(m):
        for c in range(n):
            board[r][c] >>= 1
    return board

def game_of_life(board):
    m, n = len(board), len(board[0])
    prev = [row[:] for row in board]
    def live(r, c):
        return sum(prev[nr][nc] for dr in (-1,0,1) for dc in (-1,0,1)
                   if (dr or dc) and 0 <= (nr := r+dr) < m and 0 <= (nc := c+dc) < n)
    for r in range(m):
        for c in range(n):
            cnt = live(r, c)
            board[r][c] = 1 if (board[r][c] == 1 and cnt in (2,3)) or (board[r][c] == 0 and cnt == 3) else 0
    return board

